package com.rohit.inventory.service;
import com.rohit.inventory.dto.response.*; import com.rohit.inventory.entity.*; import com.rohit.inventory.repository.*; import java.time.Instant; import java.util.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService { private final NotificationRepository notifications; private final NotificationPreferenceRepository preferences; private final UserRepository users; public NotificationService(NotificationRepository notifications,NotificationPreferenceRepository preferences,UserRepository users){this.notifications=notifications;this.preferences=preferences;this.users=users;} @Transactional public void create(String type,Notification.Severity severity,String title,String message,UUID warehouseId,UUID productId,String entityType,UUID entityId){for(User user:users.findAll()){boolean scoped=warehouseId==null||user.getRoles().stream().anyMatch(r->r.getCode().equals("ADMIN")||r.getCode().equals("INVENTORY_MANAGER"))||user.getAssignedWarehouses().stream().anyMatch(w->w.getId().equals(warehouseId));if(!scoped)continue;NotificationPreference pref=preferences.findByUserIdAndNotificationType(user.getId(),type).orElse(null);if(pref!=null&&!pref.isEnabled()&&severity!=Notification.Severity.CRITICAL)continue;Notification n=new Notification();n.setRecipient(user);n.setNotificationType(type);n.setSeverity(severity);n.setTitle(title);n.setMessage(message);n.setWarehouse(warehouseId==null?null:user.getAssignedWarehouses().stream().filter(w->w.getId().equals(warehouseId)).findFirst().orElse(null));n.setProduct(null);n.setEntityType(entityType);n.setEntityId(entityId);notifications.save(n);}} @Transactional(readOnly=true) public Page<NotificationResponse> list(String email,boolean unread,Pageable page){UUID id=users.findByEmail(email).orElseThrow().getId();return notifications.findByRecipientIdAndRead(id,unread,page).map(this::out);} @Transactional(readOnly=true) public long unread(String email){return notifications.countByRecipientIdAndRead(users.findByEmail(email).orElseThrow().getId(),false);} @Transactional public void read(String email,UUID id){Notification n=notifications.findById(id).orElseThrow();if(!n.getRecipient().getEmail().equals(email))throw new org.springframework.security.access.AccessDeniedException("Notification does not belong to user");n.setRead(true);n.setReadAt(Instant.now());} @Transactional public void readAll(String email){UUID id=users.findByEmail(email).orElseThrow().getId();notifications.findByRecipientIdAndRead(id,false,Pageable.unpaged()).forEach(n->{n.setRead(true);n.setReadAt(Instant.now());});} private NotificationResponse out(Notification n){return new NotificationResponse(n.getId(),n.getNotificationType(),n.getSeverity().name(),n.getTitle(),n.getMessage(),n.getWarehouse()==null?null:n.getWarehouse().getId(),n.getProduct()==null?null:n.getProduct().getId(),n.isRead(),n.getReadAt(),n.getCreatedAt());}}
